# -*- coding: utf-8 -*-
exec(open('lib7.py',encoding='utf-8').read())
c='p10';B='SQL 4B'
def Q(tag,title,q,desc,note,db='quanly_diem',fs=20,ofs=20,ch='Ý chính'):
    o=SQLRUN(DBSETUP(db),q)
    return S2(c,B+' · '+tag,title,card(ch,P(*desc.split('<br>')))+CODE(PRETTY(q),fs),RES(OUT(o,ofs),'Kết quả chạy SQL')+(KEY(note) if note else ''))
Q_AVG="SELECT AVG(Diem) FROM KetQua WHERE MaMon='TIN' AND NamHoc='2024-2025'"
avg=SQL1(Q_AVG,DBSETUP('quanly_diem'))
S=[]
S.append(TITLE('TIN HỌC · SQL 4B','TRUY VẤN CON<br>VÀ CÂU HỎI NÂNG CAO','Truy vấn con trong WHERE (so sánh, IN, NOT IN, EXISTS), trong FROM, truy vấn con tương quan, tìm lớn nhất / nhiều nhất kể cả khi đồng hạng, và mẫu bài HSG.',['subquery','IN','MAX','EXISTS','đồng hạng']))
S.append(goals(c,B,['Hiểu <b>truy vấn con</b> (subquery): SELECT lồng trong SELECT.','Dùng truy vấn con trả <b>một giá trị</b> (so sánh với AVG, MAX) và <b>nhiều giá trị</b> (IN).','Dùng truy vấn con trong <b>FROM</b> để tìm “tổng lớn nhất”.','Xử lí <b>đồng hạng</b>; phân biệt MAX và LIMIT 1.','Chọn giữa <b>JOIN</b> và <b>truy vấn con</b>.'],['Truy vấn con một giá trị','IN, NOT IN','FROM, đồng hạng','Tương quan, EXISTS','Tự kiểm tra']))
S.append(S2(c,B+' · 1','Truy vấn con là gì?',card('Một câu SELECT nằm trong câu khác',P('<b>Truy vấn con</b> (subquery) viết trong dấu <b>( )</b>; chạy <b>trước</b>, kết quả đưa cho truy vấn ngoài dùng.','Dùng khi điều kiện cần một <b>giá trị tính từ chính dữ liệu</b> (điểm trung bình, giá trị lớn nhất…).','Ba chỗ hay đặt: <b>WHERE</b>, <b>FROM</b>, <b>SELECT</b>.')),RES(OUT(RESQ('quanly_diem',Q_AVG),24),'Truy vấn con tính trước: điểm TB môn Tin 2024-2025')+KEY('Sau đó truy vấn ngoài so sánh điểm từng học sinh với con số này.')))
S.append(Q('1','So sánh với điểm trung bình',"SELECT MaHS, Diem FROM KetQua WHERE MaMon = 'TIN' AND NamHoc = '2024-2025' AND Diem > (SELECT AVG(Diem) FROM KetQua WHERE MaMon = 'TIN' AND NamHoc = '2024-2025')",'“Liệt kê mã học sinh có điểm môn Tin 2024-2025 <b>cao hơn điểm trung bình</b> môn Tin năm học đó của toàn trường”.<br>Không thể viết <code>Diem &gt; AVG(Diem)</code> trong WHERE; phải dùng truy vấn con.','Trung bình = %s; ai vượt mới được liệt kê.'%avg,fs=15,ch='Truy vấn con trả một giá trị'))
S.append(S2(c,B+' · 1','Vì sao WHERE không dùng trực tiếp AVG?',card('Hàm tổng hợp không dùng trong WHERE',P('<b>WHERE</b> xét <b>từng dòng</b>; AVG cần xét <b>cả tập</b> dòng.','Giải pháp: tính AVG trong <b>truy vấn con</b>, rồi so sánh.')),CODE('-- SAI\nSELECT MaHS FROM KetQua\nWHERE Diem > AVG(Diem);\n\n-- ĐÚNG\nSELECT MaHS FROM KetQua\nWHERE Diem > (SELECT AVG(Diem)\n              FROM KetQua);',20)+RES(OUT(SQLRUN(DBSETUP('quanly_diem'),'SELECT MaHS FROM KetQua WHERE Diem > AVG(Diem)'),18),'Chạy câu SAI')))
S.append(Q('1','Truy vấn con với MAX: điểm cao nhất lớp 12A1',"SELECT h.MaHS, h.TenHS, k.Diem FROM HocSinh h JOIN KetQua k ON h.MaHS = k.MaHS WHERE h.Lop = '12A1' AND k.MaMon = 'TIN' AND k.NamHoc = '2024-2025' AND k.Diem = (SELECT MAX(k2.Diem) FROM HocSinh h2 JOIN KetQua k2 ON h2.MaHS = k2.MaHS WHERE h2.Lop = '12A1' AND k2.MaMon = 'TIN' AND k2.NamHoc = '2024-2025')",'“Tìm mã và tên học sinh lớp 12A1 có điểm Tin cao nhất năm 2024-2025”.<br>Truy vấn con tìm <b>MAX</b> rồi so bằng <b>=</b>: trả <b>mọi</b> người đạt điểm đó (kể cả đồng hạng).','Nếu hai em cùng điểm cao nhất, cách này trả <b>cả hai</b>.',fs=12,ofs=22,ch='Lớn nhất, giữ đồng hạng'))
S.append(Q('2','IN: tập giá trị từ truy vấn con',"SELECT TenHS, Lop FROM HocSinh WHERE MaHS IN (SELECT MaHS FROM KetQua WHERE MaMon = 'TIN' AND Diem >= 9)",'Truy vấn con trả <b>nhiều giá trị</b> (một cột) → dùng <b>IN</b>.<br>“Học sinh có điểm Tin từ 9 trở lên”.','Giống JOIN nhưng <b>không lặp dòng</b> nếu một em có nhiều điểm ≥ 9.',fs=17,ch='Nhiều giá trị'))
S.append(Q('2','NOT IN: những học sinh chưa có điểm môn Tin',"SELECT MaHS, TenHS FROM HocSinh WHERE MaHS NOT IN (SELECT MaHS FROM KetQua WHERE MaMon = 'TIN')",'<b>NOT IN</b> loại những giá trị xuất hiện trong truy vấn con.<br>Dùng cho câu “<b>chưa từng</b> …”.','Cẩn thận: nếu truy vấn con có <b>NULL</b>, NOT IN không trả dòng nào.',fs=17,ch='“Chưa từng”'))
S.append(TB(c,B+' · 2','JOIN hay truy vấn con?',['Tình huống','Nên dùng'],[['Cần hiển thị <b>cột của nhiều bảng</b>','<b>JOIN</b>'],['Chỉ cần <b>lọc theo</b> một tập giá trị hoặc một con số','<b>Truy vấn con</b> (IN, so sánh)'],['So sánh với <b>trung bình / lớn nhất</b> của chính bảng','<b>Truy vấn con</b>'],['“Chưa từng …”','<b>NOT IN</b> hoặc <b>LEFT JOIN … IS NULL</b>'],['Cần số lượng theo nhóm rồi tìm lớn nhất','Truy vấn con trong <b>FROM</b>']],note=KEY('Nhiều bài làm được bằng cả hai cách; chọn cách <b>dễ viết đúng</b>.')))
S.append(S2(c,B+' · 3','Truy vấn con trong FROM: bảng tạm',card('Nhóm xong rồi mới tìm lớn nhất',P('Câu hỏi: “mã khách có <b>tổng giờ thuê lớn nhất</b>”.','Không thể viết <code>MAX(SUM(…))</code>. Cách làm: nhóm trước thành <b>bảng tạm t</b>, rồi lấy MAX trên t.','Truy vấn con trong FROM <b>phải có bí danh</b>.')),CODE(PRETTY("SELECT MaKT, TongGio FROM (SELECT MaKT, SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT) t WHERE TongGio = (SELECT MAX(TongGio) FROM (SELECT SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT))"),14)+RES(OUT(SQLRUN(DBSETUP('thuexe'),"SELECT MaKT, TongGio FROM (SELECT MaKT, SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT) t WHERE TongGio = (SELECT MAX(TongGio) FROM (SELECT SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT))"),24),'Kết quả chạy SQL')))
S.append(Q('3','Cách ngắn: ORDER BY … LIMIT 1','SELECT MaKT, SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT ORDER BY TongGio DESC LIMIT 1','Ngắn hơn, nhưng <b>chỉ lấy một khách</b>: nếu hai khách <b>đồng hạng</b> tổng lớn nhất, một người bị bỏ sót.','Đề nói “tất cả khách có tổng lớn nhất” → dùng cách truy vấn con (slide trước).',db='thuexe',fs=18,ch='Nhanh nhưng mất đồng hạng'))
S.append(S2(c,B+' · 3','Thử với dữ liệu có đồng hạng',card('Hai khách cùng tổng lớn nhất',P('Thêm một lượt thuê 5 giờ cho K003: K003 và K002 cùng tổng <b>12</b> giờ (lớn nhất).','So sánh LIMIT 1 với cách so bằng MAX.')),RES(OUT(SQLRUN(DBSETUP('thuexe')+"\nINSERT INTO LuotThue VALUES(13,'K003','P01','DN01',5,'2026-08-01');","SELECT MaKT, SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT ORDER BY TongGio DESC LIMIT 1"),24),'LIMIT 1: chỉ một khách')+RES(OUT(SQLRUN(DBSETUP('thuexe')+"\nINSERT INTO LuotThue VALUES(13,'K003','P01','DN01',5,'2026-08-01');","SELECT MaKT, TongGio FROM (SELECT MaKT, SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT) WHERE TongGio = (SELECT MAX(TongGio) FROM (SELECT SUM(SoGio) AS TongGio FROM LuotThue GROUP BY MaKT))"),24),'Truy vấn con: cả hai khách')))
S.append(Q('4','Truy vấn con tương quan: lượt thuê dài nhất của K002',"SELECT MaLuot, SoGio FROM LuotThue WHERE MaKT = 'K002' AND SoGio = (SELECT MAX(SoGio) FROM LuotThue WHERE MaKT = 'K002')",'“Mã lượt thuê có SoGio lớn nhất <b>trong các lượt thuê của chính khách K002</b>”.<br><b>MAX phải tính trong phạm vi K002</b>, không phải toàn bảng.','Nếu MAX tính toàn bảng sẽ cho 8 giờ (K005) và không có dòng nào của K002.',db='thuexe',fs=17,ch='Cùng phạm vi'))
S.append(Q('4','EXISTS: kiểm tra có tồn tại',"SELECT k.MaKT, k.TenKT FROM KhachThue k WHERE EXISTS (SELECT 1 FROM LuotThue l WHERE l.MaKT = k.MaKT AND l.SoGio >= 6)",'<b>EXISTS</b> đúng khi truy vấn con <b>có ít nhất một dòng</b>.<br>“Khách đã từng có lượt thuê từ 6 giờ trở lên”.','Tham chiếu <code>k.MaKT</code> ở trong: truy vấn con <b>tương quan</b> với dòng ngoài.',db='thuexe',fs=17,ch='Kiểm tra tồn tại'))
S.append(Q('4','Mẫu HSG: sách được từ 2 độc giả KHÁC NHAU mượn',"SELECT s.MaSach, s.TenSach FROM Sach s WHERE (SELECT COUNT(DISTINCT m.MaDG) FROM MuonSach m WHERE m.MaSach = s.MaSach) >= 2",'Cách khác cho bài đã làm bằng GROUP BY: <b>đếm trong truy vấn con tương quan</b>.','Cùng kết quả với GROUP BY … HAVING COUNT(DISTINCT) &gt;= 2.',db='thuvien',fs=15,ch='Đếm trong truy vấn con'))
S.append(SELF(c,B+' · 5','Tự kiểm tra 1: so với trung bình','Học sinh nào điểm Tin 2024-2025 cao hơn trung bình? Điểm trung bình là bao nhiêu?',Q_AVG,P('Điểm trung bình môn Tin 2024-2025 = <b>%s</b>.'%avg,'Học sinh vượt trung bình (chạy thật): %s.'%SQL1("SELECT MaHS FROM KetQua WHERE MaMon='TIN' AND NamHoc='2024-2025' AND Diem > (SELECT AVG(Diem) FROM KetQua WHERE MaMon='TIN' AND NamHoc='2024-2025')",DBSETUP('quanly_diem'))),20))
S.append(SELF(c,B+' · 5','Tự kiểm tra 2: MAX trong phạm vi','Vì sao câu “lượt thuê dài nhất của K002” phải đặt cùng WHERE MaKT=’K002’ trong cả truy vấn con?','SELECT MaLuot FROM LuotThue\nWHERE MaKT=\'K002\' AND SoGio =\n (SELECT MAX(SoGio) FROM LuotThue\n  WHERE MaKT=\'K002\');',P('MAX phải tính <b>chỉ trong các lượt của K002</b> (=6 giờ).','Nếu bỏ WHERE trong truy vấn con, MAX = 8 (khách K005) và truy vấn ngoài không tìm được dòng.','Chạy thật: lượt <b>%s</b>.'%SQL1("SELECT MaLuot FROM LuotThue WHERE MaKT='K002' AND SoGio=(SELECT MAX(SoGio) FROM LuotThue WHERE MaKT='K002')",DBSETUP('thuexe'))),19))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): đúng hay sai?','(a) Truy vấn con luôn viết trong ngoặc. (b) Có thể viết MAX(SUM(x)). (c) ORDER BY … LIMIT 1 xử lí đúng đồng hạng. (d) NOT IN dùng cho “chưa từng”. (e) Truy vấn con trong FROM phải có bí danh.','',P('(a) <b>Đúng</b>.','(b) <b>Sai</b>: phải nhóm trước ở truy vấn con.','(c) <b>Sai</b>: chỉ lấy một dòng.','(d) <b>Đúng</b>.','(e) <b>Đúng</b>.'),20))
S+=END(c,B,['<b>Truy vấn con</b> trong ngoặc, chạy trước.','Một giá trị → so sánh (&gt;, =); nhiều giá trị → <b>IN / NOT IN</b>.','Tìm “tổng lớn nhất”: <b>nhóm trong FROM</b> rồi MAX; chú ý <b>đồng hạng</b>.','MAX phải tính <b>đúng phạm vi</b> đề hỏi.','<b>EXISTS</b>, truy vấn con tương quan.'],[('So với trung bình','&gt; (SELECT AVG…)'),('Chưa từng','NOT IN'),('Lớn nhất giữ đồng hạng','= (SELECT MAX…)'),('Có tồn tại','EXISTS')],'Dùng AVG trong WHERE; LIMIT 1 khi đồng hạng; MAX sai phạm vi; quên bí danh bảng tạm.',['NOT IN với NULL.','<b>ANY/ALL</b>.','Truy vấn con có thể thay bằng JOIN.'],['<b>CTE (WITH)</b>.','<b>Window function</b>.','Tối ưu truy vấn con tương quan.'],
 [('Truy vấn con viết trong?',),('Lọc theo tập nhiều giá trị?',),('Chưa từng?',),('Tổng lớn nhất, giữ đồng hạng?',),('Có tồn tại?',)],
 [('Dấu <b>( )</b>.',),('<b>IN</b>.',),('<b>NOT IN</b>.',),('Truy vấn con MAX.',),('<b>EXISTS</b>.',)],
 [('Mức 1. Học sinh có điểm Toán cao hơn trung bình môn Toán.',),('Mức 1. Sách chưa từng được mượn.',),('Mức 2. Độc giả có tổng số ngày mượn lớn hơn trung bình các độc giả.',),('Mức 2. Lượt thuê có số giờ lớn nhất trong trạm DN01.',),('Mức 3 (HSG). Tìm mã khách có tổng giờ lớn nhất, đúng cả khi đồng hạng.',),('Mức 3 (HSG). Nhạc sĩ có số bản thu âm nhiều nhất.',)],
 [('<code>Diem &gt; (SELECT AVG…)</code>.',),('<code>NOT IN</code> / LEFT JOIN.',),('Truy vấn con tính SUM theo độc giả rồi AVG.',),('<code>= (SELECT MAX… WHERE Tram=\'DN01\')</code>.',),('Slide “Truy vấn con trong FROM”.',),('Nhóm theo nhạc sĩ, so với MAX của các nhóm.',)],hper=2)
mkdeck('c4b.html','SQL 4B · Truy vấn con và nâng cao',S)
